<?php
/**
 * CRM logic tests (Phase 6): authorization, leads, deduplication, pipeline, proposals, revenue, campaigns, partners, business development, dashboard.
 * Runs against the ISOLATED test database only (name must contain "test"). Synthetic data; no mail, no network.
 */
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }
ob_start();   // keep session functions usable in CLI
$root = dirname(__DIR__);
require_once $root . '/helpers.php';
require_once $root . '/crm_dashboard.php';
$pass = 0; $fail = 0;
function ok(bool $c, string $m): void { global $pass, $fail; if ($c) $pass++; else { $fail++; fwrite(STDERR, "  FAIL: $m\n"); } }
function section(string $t): void { fwrite(STDERR, "== $t\n"); }
if (stripos((string)sec_setting('AIHUB_DB_NAME', 'db.name'), 'test') === false) { fwrite(STDERR, "Refusing: database name must contain 'test'\n"); exit(2); }
db_connection_available(); $pdo = crm_pdo();
if (!crm_tables_ready()) { fwrite(STDERR, "CRM tables missing: apply database/phase6_crm.sql to the test database\n"); exit(2); }
foreach (['crm_audit_log', 'crm_outreach_drafts', 'crm_prospects', 'crm_partners', 'crm_campaigns', 'crm_revenue_entries', 'crm_contracts', 'crm_proposal_items', 'crm_proposal_versions', 'crm_proposals', 'crm_tasks', 'crm_activities', 'crm_stage_history', 'crm_opportunities', 'crm_leads', 'crm_contacts', 'crm_companies', 'crm_users'] as $t) $pdo->exec("DELETE FROM $t");
$H = password_hash('test-only-password', PASSWORD_DEFAULT);
[, $ownerId] = crm_user_create($pdo, 'owner1', 'Olivia Owner', 'owner', $H); [, $salesId] = crm_user_create($pdo, 'sales1', 'Sam Sales', 'sales', $H); [, $viewId] = crm_user_create($pdo, 'viewer1', 'Vera Viewer', 'viewer', $H);
$owner = crm_user_get($pdo, (int)$ownerId); $sales = crm_user_get($pdo, (int)$salesId); $viewer = crm_user_get($pdo, (int)$viewId);

section('Roles and users');
ok(crm_can('owner', 'approve') && crm_can('owner', 'revenue') && !crm_can('sales', 'approve') && !crm_can('sales', 'revenue') && crm_can('sales', 'write') && !crm_can('viewer', 'write') && crm_can('viewer', 'read') && !crm_can(null, 'read') && !crm_can('ghost', 'read'), 'permission matrix');
ok(crm_user_create($pdo, 'x', 'N', 'owner', $H)[1] === 'username_invalid' && crm_user_create($pdo, 'owner1', 'Dup', 'owner', $H)[1] === 'username_taken' && crm_user_create($pdo, 'newuser', 'N', 'root', $H)[1] === 'role_invalid' && crm_user_create($pdo, 'newuser', 'N', 'owner', 'plaintext')[1] === 'hash_invalid', 'user creation validates username, role and requires a password hash');
ok(!(bool)$pdo->query("SELECT 1 FROM crm_users WHERE password_hash = 'test-only-password'")->fetchColumn() && strpos((string)$pdo->query("SELECT password_hash FROM crm_users LIMIT 1")->fetchColumn(), '$') === 0, 'passwords are stored only as hashes');
[$c1, $u1] = crm_login($pdo, 'owner1', 'wrong'); ok($c1 === 'invalid' && $u1 === null, 'wrong password is refused');
[$c2] = crm_login($pdo, 'ghost', 'test-only-password'); ok($c2 === 'invalid', 'unknown user is refused with the same answer');
$pdo->exec("UPDATE crm_users SET active = 0 WHERE username = 'viewer1'"); [$c3] = crm_login($pdo, 'viewer1', 'test-only-password'); ok($c3 === 'invalid', 'a deactivated user cannot sign in'); $pdo->exec("UPDATE crm_users SET active = 1 WHERE username = 'viewer1'");
[$c4, $u4] = crm_login($pdo, 'owner1', 'test-only-password'); ok($c4 === 'ok' && $u4['role'] === 'owner' && !isset($u4['password_hash']), 'correct credentials sign in and expose no hash');
ok(crm_current_user($pdo)['username'] === 'owner1', 'the session resolves the current user'); $_SESSION['crm_at'] = time() - CRM_IDLE_SECONDS - 5; ok(crm_current_user($pdo) === null, 'an idle session expires');
foreach (glob((getenv('AIHUB_RATE_DIR') ?: '/nonexistent') . '/*') ?: [] as $f) @unlink($f);

section('Money helpers');
ok(crm_money_parse('1234.56') === 123456 && crm_money_parse('1 234,5') === 123450 && crm_money_parse('0') === 0 && crm_money_parse('7') === 700 && crm_money_parse('1.234') === null && crm_money_parse('-5') === null && crm_money_parse('abc') === null && crm_money_parse('') === null && crm_money_parse('1e5') === null, 'amount parsing is strict');
ok(crm_money_format(123456, 'EUR') === '1,234.56 EUR' && crm_money_format(5, 'USD') === '0.05 USD', 'amount formatting');
ok(crm_percent_to_bp('19') === 1900 && crm_percent_to_bp('19.5') === 1950 && crm_percent_to_bp('') === 0 && crm_percent_to_bp('100') === 10000 && crm_percent_to_bp('101') === null && crm_percent_to_bp('-1') === null, 'percent to basis points');
ok(crm_domain('https://www.Example.com/x?y=1') === 'example.com' && crm_domain('example.co.uk') === 'example.co.uk' && crm_domain('javascript:alert(1)') === '' && crm_domain('localhost') === '', 'domain extraction');
ok(crm_scrub('mail a.b+c@example.com now') === 'mail [email] now' && crm_mask_email('alice@example.com') === 'a***@example.com', 'email scrubbing and masking');

section('Proposal calculations');
$t = proposal_totals([['qty_x100' => 200, 'unit_minor' => 150000, 'discount_bp' => 1000], ['qty_x100' => 150, 'unit_minor' => 9999]], 500, 1900);
ok($t['ok'] && $t['lines'][0]['line_total_minor'] === 270000 && $t['lines'][1]['line_total_minor'] === 14999 && $t['subtotal_minor'] === 284999 && $t['discount_minor'] === 14250 && $t['tax_minor'] === 51442 && $t['total_minor'] === 322191, 'worked example: subtotal 2,849.99, discount 142.50, tax 514.42, total 3,221.91');
ok(proposal_totals([['qty_x100' => 50, 'unit_minor' => 1]])['total_minor'] === 1 && proposal_totals([['qty_x100' => 150, 'unit_minor' => 1]])['total_minor'] === 2, 'half-up rounding (0.5 cent rounds up)');
foreach ([[[], 0, 0, 'no_items'], [[['qty_x100' => 0, 'unit_minor' => 1]], 0, 0, 'qty_invalid'], [[['qty_x100' => 100, 'unit_minor' => -1]], 0, 0, 'unit_invalid'], [[['qty_x100' => 100, 'unit_minor' => 1, 'discount_bp' => 10001]], 0, 0, 'line_discount_invalid'], [[['qty_x100' => 100, 'unit_minor' => 1]], 10001, 0, 'discount_invalid'], [[['qty_x100' => 100, 'unit_minor' => 1]], 0, -1, 'tax_invalid'], [[['qty_x100' => 100, 'unit_minor' => CRM_MAX_UNIT_MINOR + 1]], 0, 0, 'unit_invalid'], [[['qty_x100' => CRM_MAX_QTY_X100 + 1, 'unit_minor' => 1]], 0, 0, 'qty_invalid']] as [$it, $d, $x, $err]) { $r = proposal_totals($it, $d, $x); ok(!$r['ok'] && $r['error'] === $err, "rejected: $err"); }
$bigItems = array_fill(0, CRM_MAX_ITEMS, ['qty_x100' => CRM_MAX_QTY_X100, 'unit_minor' => CRM_MAX_UNIT_MINOR]); $big = proposal_totals($bigItems, 10000, 10000); $big2 = proposal_totals($bigItems, 5000, 2500);
ok($big['ok'] && $big['total_minor'] === 0 && is_int($big['subtotal_minor']) && $big['subtotal_minor'] === 500000000000000 && $big2['ok'] && is_int($big2['total_minor']) && $big2['total_minor'] === 250000000000000 + 62500000000000 && proposal_totals(array_fill(0, CRM_MAX_ITEMS + 1, $bigItems[0]))['error'] === 'too_many_items', 'maximum values (50 lines) stay exact integers: no overflow, 100% discount gives zero, over 50 lines refused');
mt_srand(42); $okAll = true; for ($i = 0; $i < 300; $i++) { $n = mt_rand(1, 5); $its = []; for ($j = 0; $j < $n; $j++) $its[] = ['qty_x100' => mt_rand(1, 100000), 'unit_minor' => mt_rand(0, 5000000), 'discount_bp' => mt_rand(0, 10000)]; $r = proposal_totals($its, mt_rand(0, 10000), mt_rand(0, 3000)); $sum = array_sum(array_column($r['lines'], 'line_total_minor')); if (!$r['ok'] || $sum !== $r['subtotal_minor'] || $r['total_minor'] !== $r['subtotal_minor'] - $r['discount_minor'] + $r['tax_minor'] || $r['total_minor'] < 0 || $r['discount_minor'] > $r['subtotal_minor']) { $okAll = false; break; } }
ok($okAll, '300 random proposals keep total = subtotal - discount + tax, line sums consistent, nothing negative');

section('Lead ingestion, deduplication and authorization');
$in = ['kind' => 'advertising', 'subtype' => 'advertiser', 'name' => 'Ada Tester', 'email' => 'Ada@Acme-Test.example', 'company' => 'Acme Test Ltd', 'website' => 'https://www.acme-test.example/about', 'message' => 'We would like a featured placement.', 'budget' => '5k-20k', 'timeline' => '1-3-months', 'source' => '/advertise.php', 'attr_source' => 'mockletter', 'attr_campaign' => 'p6-test', 'synthetic' => true];
[$ok1, $lead1, $info1] = crm_lead_ingest($pdo, $in);
ok($ok1 && $info1['duplicate_of'] === null && (int)$pdo->query('SELECT COUNT(*) FROM crm_companies')->fetchColumn() === 1 && (int)$pdo->query('SELECT COUNT(*) FROM crm_contacts')->fetchColumn() === 1, 'an inquiry creates one company, one contact and one lead');
$L = crm_lead_get($pdo, $lead1); ok($L['status'] === 'new' && $L['company_domain'] === 'acme-test.example' && $L['contact_email'] === 'ada@acme-test.example' && $L['consent_status'] === 'inbound_inquiry' && $L['attr_campaign'] === 'p6-test', 'normalised email and domain; inbound inquiry is not marketing consent');
[$ok2, $lead2, $info2] = crm_lead_ingest($pdo, ['name' => 'Ada T', 'email' => ' ADA@acme-test.example '] + $in);
ok($ok2 && $info2['duplicate_of'] === $lead1 && (int)$pdo->query('SELECT COUNT(*) FROM crm_contacts')->fetchColumn() === 1 && (int)$pdo->query('SELECT COUNT(*) FROM crm_companies')->fetchColumn() === 1, 'the same email is detected as a duplicate: no second contact or company, the lead is flagged');
[$ok3, $lead3, $info3] = crm_lead_ingest($pdo, ['name' => 'Bob Colleague', 'email' => 'bob@acme-test.example', 'company' => 'ACME TEST LTD'] + $in);
ok($ok3 && $info3['company_id'] === $info1['company_id'] && $info3['duplicate_of'] === null && (int)$pdo->query('SELECT COUNT(*) FROM crm_contacts')->fetchColumn() === 2, 'a colleague at the same domain joins the same company without being a duplicate');
[, , $info4] = crm_lead_ingest($pdo, ['kind' => 'development', 'name' => 'Free Mail', 'email' => 'someone@gmail.com', 'company' => 'Gmail Co One', 'message' => 'hi', 'synthetic' => true]);
[, , $info5] = crm_lead_ingest($pdo, ['kind' => 'development', 'name' => 'Free Mail 2', 'email' => 'other@gmail.com', 'company' => 'Gmail Co Two', 'message' => 'hi', 'synthetic' => true]);
ok($info4['company_id'] !== $info5['company_id'], 'free email providers never merge unrelated companies');
ok(crm_lead_ingest($pdo, ['email' => 'nope'] + $in)[1] === 'email_invalid' && crm_lead_ingest($pdo, ['name' => ''] + $in)[1] === 'name_required' && crm_lead_ingest($pdo, ['kind' => 'x'] + $in)[1] === 'kind_invalid' && crm_lead_ingest($pdo, ['email' => "a@b.example\r\nBcc: x@y.example"] + $in)[1] === 'email_invalid', 'ingestion validates kind, name and email (header injection refused)');
$before = (int)$pdo->query('SELECT COUNT(*) FROM crm_leads')->fetchColumn(); crm_lead_ingest($pdo, ['email' => 'bad'] + $in); ok((int)$pdo->query('SELECT COUNT(*) FROM crm_leads')->fetchColumn() === $before, 'refused inquiries store nothing');
[, $hostile] = crm_lead_ingest($pdo, ['name' => "<script>alert(1)</script>'; DROP TABLE crm_leads;--", 'email' => 'h@hostile.example', 'company' => "Evil'; DELETE FROM crm_users;--", 'message' => str_repeat('A', 9000), 'details' => ['x' => '<b>y</b>'], 'synthetic' => true] + $in);
ok((int)$pdo->query('SELECT COUNT(*) FROM crm_users')->fetchColumn() === 3 && $pdo->query('SELECT COUNT(*) FROM crm_leads')->fetchColumn() > 0 && strlen(crm_lead_get($pdo, (int)$hostile)['message']) === 4000, 'hostile text is stored as inert data and long messages are truncated');
ok(crm_lead_assign($pdo, $viewer, (int)$lead1, (int)$salesId)[1] === 'forbidden' && crm_lead_assign($pdo, $sales, (int)$lead1, 99999)[1] === 'assignee_invalid' && crm_lead_assign($pdo, $sales, (int)$lead1, (int)$salesId) === [true, 'ok'] && crm_lead_get($pdo, (int)$lead1)['assignee'] === 'Sam Sales', 'assignment: viewers refused, unknown assignee refused, sales can assign');
ok(crm_lead_qualify($pdo, $viewer, (int)$lead1, [], 'qualified')[1] === 'forbidden' && crm_lead_qualify($pdo, $sales, (int)$lead1, [], 'maybe')[1] === 'decision_invalid' && crm_lead_qualify($pdo, $sales, (int)$lead1, [], 'disqualified')[1] === 'reason_required', 'qualification: viewers refused, invalid decision refused, disqualifying needs a reason');
ok(crm_lead_convert($pdo, $sales, (int)$lead1, '', '1000', 'EUR')[1] === 'lead_not_qualified', 'only a qualified lead can be converted');
[$qok, $score] = crm_lead_qualify($pdo, $sales, (int)$lead1, ['need' => 'yes', 'budget' => 'yes', 'timeline' => 'unknown', 'authority' => 'bogus'], 'qualified');
ok($qok && $score === '2' && json_decode(crm_lead_get($pdo, (int)$lead1)['qualification'], true)['answers']['authority'] === 'unknown', 'qualification score is the count of "yes" answers; unexpected values become unknown');
$before = (int)$pdo->query('SELECT COUNT(*) FROM crm_opportunities')->fetchColumn(); $r = crm_lead_convert($pdo, $sales, (int)$lead1, 'Acme featured', '1500', 'XXX');
ok($r[1] === 'currency_invalid' && crm_lead_get($pdo, (int)$lead1)['status'] === 'qualified' && (int)$pdo->query('SELECT COUNT(*) FROM crm_opportunities')->fetchColumn() === $before, 'a failed conversion changes nothing (transaction rolled back)');
[$cok, $opp1] = crm_lead_convert($pdo, $sales, (int)$lead1, 'Acme featured placement', '1500.00', 'EUR', '2027-01-31');
ok($cok && crm_lead_get($pdo, (int)$lead1)['status'] === 'converted' && crm_opp_get($pdo, (int)$opp1)['stage'] === 'qualified' && (int)crm_opp_get($pdo, (int)$opp1)['amount_minor'] === 150000, 'conversion creates a qualified opportunity and marks the lead converted');
ok(crm_lead_qualify($pdo, $sales, (int)$lead1, [], 'qualified')[1] === 'already_converted', 'a converted lead cannot be requalified');
$f = crm_leads_list($pdo, ['kind' => 'advertising']); ok($f['total'] === 4 && count(array_filter($f['rows'], fn($r) => $r['duplicate_of'])) === 1, 'list filter by kind');
ok(crm_leads_list($pdo, ['status' => 'converted'])['total'] === 1 && crm_leads_list($pdo, ['assigned' => (int)$salesId])['total'] === 1 && crm_leads_list($pdo, ['assigned' => 'none'])['total'] >= 3 && crm_leads_list($pdo, ['source' => 'mockletter'])['total'] >= 3 && crm_leads_list($pdo, ['duplicates' => 1])['total'] === 1, 'list filters: status, assignee, unassigned, source, duplicates');
ok(crm_leads_list($pdo, ['q' => 'acme'])['total'] >= 3 && crm_leads_list($pdo, ['q' => '%'])['total'] === 0 && crm_leads_list($pdo, ['q' => "' OR '1'='1"])['total'] === 0 && crm_leads_list($pdo, ['q' => 'ada@acme'])['total'] >= 1, 'search matches company/contact/email; wildcard and SQL-injection input match nothing special');
ok(crm_leads_list($pdo, ['kind' => 'bogus; DROP TABLE crm_leads'])['total'] > 0, 'an unknown filter value is ignored, not executed');

section('Opportunities and pipeline');
$ok_all = true; foreach (array_keys(crm_stages()) as $a) foreach (array_keys(crm_stages()) as $b) { $exp = false; $open = crm_open_stages(); if (in_array($a, $open, true)) { if ($b === 'lost') $exp = true; elseif ($b === 'won') $exp = $a === 'negotiation'; elseif (in_array($b, $open, true)) $exp = array_search($b, $open) > array_search($a, $open); } if (crm_opp_can_move($a, $b) !== $exp) { $ok_all = false; fwrite(STDERR, "  transition $a→$b\n"); } } ok($ok_all, 'complete stage transition matrix (forward only, won only from negotiation, lost from any open stage, closed is final)');
ok(crm_opp_move($pdo, $viewer, (int)$opp1, 'contacted')[1] === 'forbidden' && crm_opp_move($pdo, $sales, (int)$opp1, 'new')[1] === 'transition_invalid' && crm_opp_move($pdo, $sales, (int)$opp1, 'won')[1] === 'transition_invalid', 'viewers cannot move; no backwards or skip-to-won');
foreach (['contacted', 'discovery', 'proposal', 'negotiation'] as $st) ok(crm_opp_move($pdo, $sales, (int)$opp1, $st) === [true, 'ok'], "move to $st");
ok(count(crm_opp_history($pdo, (int)$opp1)) === 5 && crm_opp_history($pdo, (int)$opp1)[4]['to_stage'] === 'negotiation', 'every stage change is recorded in the history');
[, $oppZero] = crm_opp_create($pdo, $sales, (int)$info1['company_id'], null, 'advertising', 'Zero value', '', 'EUR', null, null, 'negotiation'); ok(crm_opp_move($pdo, $sales, (int)$oppZero, 'won')[1] === 'amount_required_for_won', 'an opportunity without an amount cannot be won');
ok(crm_opp_move($pdo, $sales, (int)$oppZero, 'lost')[1] === 'lost_reason_required' && crm_opp_move($pdo, $sales, (int)$oppZero, 'lost', 'No budget') === [true, 'ok'] && crm_opp_get($pdo, (int)$oppZero)['outcome'] === 'lost' && crm_opp_get($pdo, (int)$oppZero)['lost_reason'] === 'No budget', 'losing needs a reason and records the outcome');
ok(crm_opp_move($pdo, $sales, (int)$oppZero, 'negotiation')[1] === 'transition_invalid' && crm_opp_update($pdo, $sales, (int)$oppZero, ['title' => 'x'])[1] === 'closed', 'a closed opportunity is final');
ok(crm_opp_create($pdo, $viewer, (int)$info1['company_id'], null, 'advertising', 'x', '1', 'EUR')[1] === 'forbidden' && crm_opp_create($pdo, $sales, 99999, null, 'advertising', 'x', '1', 'EUR')[1] === 'company_invalid' && crm_opp_create($pdo, $sales, (int)$info1['company_id'], null, 'advertising', 'x', '1.999', 'EUR')[1] === 'amount_invalid' && crm_opp_create($pdo, $sales, (int)$info1['company_id'], null, 'advertising', '', '1', 'EUR')[1] === 'title_required' && crm_opp_create($pdo, $sales, (int)$info1['company_id'], null, 'advertising', 'x', '1', 'EUR', 'not a date')[1] === 'close_date_invalid', 'opportunity validation');
ok(crm_opp_update($pdo, $sales, (int)$opp1, ['owner_id' => (int)$ownerId])[0] === true && crm_opp_update($pdo, $viewer, (int)$opp1, ['title' => 'hack'])[1] === 'forbidden' && crm_opp_get($pdo, (int)$opp1)['owner'] === 'Olivia Owner', 'opportunity update and owner assignment');
ok(count(crm_opps_list($pdo, ['open' => 1])) === 1 && count(crm_opps_list($pdo, ['stage' => 'lost'])) === 1 && count(crm_opps_list($pdo, ['q' => 'zero'])) === 1 && count(crm_opps_list($pdo, ['kind' => 'advertising'])) === 2, 'opportunity filters');

section('Proposals, versions and approvals');
$pin = ['currency' => 'EUR', 'discount' => '5', 'tax' => '19', 'billing_period' => 'monthly', 'valid_until' => gmdate('Y-m-d', time() + 20 * 86400), 'terms' => 'Internal draft terms.', 'items' => [['description' => 'Featured placement', 'qty' => '2', 'unit' => '1500.00', 'discount' => '10'], ['description' => 'Setup', 'qty' => '1.5', 'unit' => '99.99', 'discount' => '']]];
ok(crm_proposal_create($pdo, $viewer, (int)$opp1, $pin)[1] === 'forbidden' && crm_proposal_create($pdo, $sales, 99999, $pin)[1] === 'opportunity_invalid' && crm_proposal_create($pdo, $sales, (int)$opp1, ['currency' => 'XXX'] + $pin)[1] === 'currency_invalid' && crm_proposal_create($pdo, $sales, (int)$opp1, ['items' => []] + $pin)[1] === 'no_items' && crm_proposal_create($pdo, $sales, (int)$opp1, ['valid_until' => '2000-01-01'] + $pin)[1] === 'valid_until_past' && crm_proposal_create($pdo, $sales, (int)$opp1, ['items' => [['description' => 'x', 'qty' => '1', 'unit' => '9.999']]] + $pin)[1] === 'item_invalid', 'proposal validation and authorization');
ok((int)$pdo->query('SELECT COUNT(*) FROM crm_proposals')->fetchColumn() === 0, 'rejected proposals leave no orphan rows');
[$pk, $pid] = crm_proposal_create($pdo, $sales, (int)$opp1, $pin); $P = crm_proposal_get($pdo, (int)$pid);
ok($pk && $P['status'] === 'draft' && (int)$P['total_minor'] === 322191 && preg_match('/^P-\d{4}-\d{4}$/', $P['number']) && count(crm_proposal_items($pdo, (int)$P['version_id'])) === 2, 'a proposal is stored with computed totals and a number');
ok(crm_proposal_set_status($pdo, $sales, (int)$pid, 'approved')[1] === 'transition_invalid' && crm_proposal_set_status($pdo, $sales, (int)$pid, 'pending_approval') === [true, 'ok'] && crm_proposal_set_status($pdo, $sales, (int)$pid, 'approved')[1] === 'forbidden' && crm_proposal_set_status($pdo, $owner, (int)$pid, 'approved') === [true, 'ok'], 'approval needs the owner role and the right sequence');
ok(crm_proposal_set_status($pdo, $sales, (int)$pid, 'accepted')[1] === 'forbidden', 'recording the customer decision needs revenue rights');
$r2 = crm_proposal_revise($pdo, $sales, (int)$pid, ['items' => [['description' => 'Featured placement', 'qty' => '1', 'unit' => '1000', 'discount' => '']], 'tax' => '0', 'discount' => '0'] + $pin);
$P2 = crm_proposal_get($pdo, (int)$pid); ok($r2 === [true, '2'] && $P2['status'] === 'draft' && (int)$P2['total_minor'] === 100000 && count(crm_proposal_versions($pdo, (int)$pid)) === 2 && (int)$pdo->query("SELECT total_minor FROM crm_proposal_versions WHERE proposal_id = $pid AND version = 1")->fetchColumn() === 322191, 'a revision creates version 2, returns to draft and keeps version 1 intact');
crm_proposal_set_status($pdo, $owner, (int)$pid, 'pending_approval'); crm_proposal_set_status($pdo, $owner, (int)$pid, 'approved');
ok(crm_proposal_set_status($pdo, $owner, (int)$pid, 'accepted') === [true, 'ok'] && crm_proposal_revise($pdo, $sales, (int)$pid, $pin)[1] === 'proposal_closed', 'an accepted proposal can no longer be edited');

section('Contracts and revenue classification');
$base = crm_revenue_summary($pdo); ok(($base['EUR']['proposed'] ?? 0) === 0 && ($base['EUR']['contracted'] ?? 0) === 0 && ($base['EUR']['mrr'] ?? 0) === 0, 'an accepted proposal is not contracted revenue and not MRR');
